1	//! Owned scanout-consumer ledger. Platform code must finish rendering/acquire
2	//! before preparing a frame and supply genuine cookie-bearing DRM completions.
3	//! No KMS submitter or live compositor integration is provided by this module.
4	use crate::Ticket;
5	use serde::Serialize;
6	use std::{
7	    cell::RefCell,
8	    collections::BTreeSet,
9	    rc::Rc,
10	    sync::atomic::{AtomicU64, Ordering},
11	};
12	pub const MAX_FRAME_SLOTS: usize = 64;
13	pub const MAX_FRAME_BYTES: u64 = 256 * 1024 * 1024;
14	pub const MAX_OUTPUTS: usize = 32;
15	static LAST_COOKIE: AtomicU64 = AtomicU64::new(0);
16	#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
17	#[serde(transparent)]
18	pub struct Cookie(#[serde(serialize_with = "decimal")] u64);
19	impl Cookie {
20	    pub fn get(self) -> u64 {
21	        self.0
22	    }
23	}
24	fn decimal<S: serde::Serializer>(value: &u64, serializer: S) -> Result<S::Ok, S::Error> {
25	    serializer.serialize_str(&value.to_string())
26	}
27	fn allocate_cookie(counter: &AtomicU64) -> Result<Cookie, Error> {
28	    counter
29	        .try_update(Ordering::Relaxed, Ordering::Relaxed, |old| {
30	            old.checked_add(1)
31	        })
32	        .map(|old| Cookie(old + 1))
33	        .map_err(|_| Error::Exhausted)
34	}
35	#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize)]
36	pub struct OutputKey {
37	    #[serde(serialize_with = "decimal")]
38	    device: u64,
39	    #[serde(serialize_with = "decimal")]
40	    generation: u64,
41	    #[serde(serialize_with = "decimal")]
42	    session_epoch: u64,
43	    crtc: u32,
44	    #[serde(serialize_with = "decimal")]
45	    output_epoch: u64,
46	}
47	impl OutputKey {
48	    pub fn new(ticket: Ticket, crtc: u32, output_epoch: u64) -> Result<Self, Error> {
49	        if ticket.generation == 0 || ticket.session_epoch == 0 || crtc == 0 || output_epoch == 0 {
50	            return Err(Error::InvalidKey);
51	        }
52	        Ok(Self {
53	            device: ticket.device,
54	            generation: ticket.generation,
55	            session_epoch: ticket.session_epoch,
56	            crtc,
57	            output_epoch,
58	        })
59	    }
60	    fn source_matches(self, source: Ticket, crtc: u32) -> bool {
61	        self.device == source.device
62	            && self.generation == source.generation
63	            && self.session_epoch == source.session_epoch
64	            && self.crtc == crtc
65	    }
66	}
67	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
68	pub enum Error {
69	    InvalidKey,
70	    Capacity,
71	    DuplicateOutput,
72	    WrongPool,
73	    Inactive,
74	    Pending,
75	    Exhausted,
76	    WrongProof,
77	}
78	#[derive(Default)]
79	struct Budget {
80	    slots: usize,
81	    bytes: u64,
82	    orphaned: usize,
83	    orphaned_bytes: u64,
84	    outputs: BTreeSet<OutputKey>,
85	}
86	#[derive(Clone, Default)]
87	pub struct FramePool {
88	    state: Rc<RefCell<Budget>>,
89	}
90	#[derive(Debug, PartialEq, Eq, Serialize)]
91	pub struct PoolSnapshot {
92	    pub slots: usize,
93	    pub nominal_bytes: String,
94	    pub orphaned: usize,
95	    pub orphaned_nominal_bytes: String,
96	    pub outputs: usize,
97	}
98	impl FramePool {
99	    pub fn snapshot(&self) -> PoolSnapshot {
100	        let state = self.state.borrow();
101	        PoolSnapshot {
102	            slots: state.slots,
103	            nominal_bytes: state.bytes.to_string(),
104	            orphaned: state.orphaned,
105	            orphaned_nominal_bytes: state.orphaned_bytes.to_string(),
106	            outputs: state.outputs.len(),
107	        }
108	    }
109	    /// Reserve before allocation. The callback must return only after all GPU
110	    /// rendering/acquire work has completed. Bytes account nominal payload only.
111	    pub fn prepare<R, S, E>(
112	        &self,
113	        bytes: u64,
114	        allocate: impl FnOnce() -> Result<(R, S), E>,
115	    ) -> Result<PreparedFrame<R, S>, PreparationError<E>> {
116	        {
117	            let mut state = self.state.borrow_mut();
118	            if bytes == 0
119	                || bytes > MAX_FRAME_BYTES
120	                || state.slots == MAX_FRAME_SLOTS
121	                || state.bytes > MAX_FRAME_BYTES - bytes
122	            {
123	                return Err(PreparationError::Admission(Error::Capacity));
124	            }
125	            state.slots += 1;
126	            state.bytes += bytes;
127	        }
128	        let permit = Permit {
129	            pool: self.clone(),
130	            bytes,
131	        };
132	        let (resource, scene) = allocate().map_err(PreparationError::Backend)?;
133	        Ok(PreparedFrame {
134	            payload: Some(Payload {
135	                resource,
136	                scene,
137	                permit,
138	            }),
139	            consuming: false,
140	        })
141	    }
142	    pub fn output<R, S>(&self, key: OutputKey) -> Result<FrameQueue<R, S>, Error> {
143	        {
144	            let mut state = self.state.borrow_mut();
145	            if state.outputs.contains(&key) {
146	                return Err(Error::DuplicateOutput);
147	            }
148	            if state.outputs.len() == MAX_OUTPUTS {
149	                return Err(Error::Capacity);
150	            }
151	            state.outputs.insert(key);
152	        }
153	        Ok(FrameQueue {
154	            key,
155	            front: None,
156	            pending: None,
157	            active: true,
158	            faulted: false,
159	            closed: false,
160	            _output: OutputPermit {
161	                pool: self.clone(),
162	                key,
163	            },
164	        })
165	    }
166	}
167	#[derive(Debug, PartialEq, Eq)]
168	pub enum PreparationError<E> {
169	    Admission(Error),
170	    Backend(E),
171	}
172	struct Permit {
173	    pool: FramePool,
174	    bytes: u64,
175	}
176	impl Drop for Permit {
177	    fn drop(&mut self) {
178	        let mut state = self.pool.state.borrow_mut();
179	        state.slots -= 1;
180	        state.bytes -= self.bytes;
181	    }
182	}
183	struct OutputPermit {
184	    pool: FramePool,
185	    key: OutputKey,
186	}
187	impl Drop for OutputPermit {
188	    fn drop(&mut self) {
189	        self.pool.state.borrow_mut().outputs.remove(&self.key);
190	    }
191	}
192	struct Payload<R, S> {
193	    resource: R,
194	    scene: S,
195	    permit: Permit,
196	}
197	/// Prepared resources cannot be cloned/extracted. Dropping a submitted/front
198	/// frame without completion leaks its payload AND quota permit deliberately;
199	/// it never manufactures consumer completion. One pool must own a backend's
200	/// whole lifetime so those fail-closed reservations cannot be bypassed by reset.
201	pub struct PreparedFrame<R, S> {
202	    payload: Option<Payload<R, S>>,
203	    consuming: bool,
204	}
205	impl<R, S> Drop for PreparedFrame<R, S> {
206	    fn drop(&mut self) {
207	        if self.consuming
208	            && let Some(payload) = self.payload.take()
209	        {
210	            {
211	                let mut state = payload.permit.pool.state.borrow_mut();
212	                state.orphaned += 1;
213	                state.orphaned_bytes += payload.permit.bytes;
214	            }
215	            std::mem::forget(payload);
216	        }
217	    }
218	}
219	/// All resources remain owned on uncertain submission. A definite rejection
220	/// requires a platform guarantee that KMS never accepted any consumer.
221	pub enum SubmitOutcome<E> {
222	    Accepted,
223	    Rejected(E),
224	    Uncertain(E),
225	}
226	pub enum SubmitError<R, S, E> {
227	    Admission {
228	        reason: Error,
229	        frame: PreparedFrame<R, S>,
230	    },
231	    Rejected {
232	        error: E,
233	        frame: PreparedFrame<R, S>,
234	    },
235	    Uncertain(E),
236	}
237	struct Pending<R, S> {
238	    cookie: Cookie,
239	    frame: PreparedFrame<R, S>,
240	}
241	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
242	pub enum Completion {
243	    Ignored,
244	    Presented,
245	    RetiredProgress,
246	}
247	#[derive(Debug, Serialize)]
248	pub struct QueueSnapshot {
249	    pub key: OutputKey,
250	    pub active: bool,
251	    pub faulted: bool,
252	    pub closed: bool,
253	    pub front_cookie: Option<Cookie>,
254	    pub pending_cookie: Option<Cookie>,
255	}
256	struct Front<R, S> {
257	    cookie: Cookie,
258	    frame: PreparedFrame<R, S>,
259	}
260	pub struct FrameQueue<R, S> {
261	    key: OutputKey,
262	    front: Option<Front<R, S>>,
263	    pending: Option<Pending<R, S>>,
264	    active: bool,
265	    faulted: bool,
266	    closed: bool,
267	    _output: OutputPermit,
268	}
269	/// This witness is an unsafe backend boundary, never an IPC acknowledgement.
270	pub struct IdleProof {
271	    key: OutputKey,
272	}
273	impl IdleProof {
274	    /// # Safety
275	    /// Every scanout consumer for this exact output epoch, including every
276	    /// accepted/uncertain queued frame, must have conclusively stopped. Pause,
277	    /// timeout, ioctl rejection, FD-number reuse and hotplug alone are not proof.
278	    pub unsafe fn after_backend_quiescence(key: OutputKey) -> Self {
279	        Self { key }
280	    }
281	}
282	impl<R, S> FrameQueue<R, S> {
283	    pub fn snapshot(&self) -> QueueSnapshot {
284	        QueueSnapshot {
285	            key: self.key,
286	            active: self.active,
287	            faulted: self.faulted,
288	            closed: self.closed,
289	            front_cookie: self.front.as_ref().map(|f| f.cookie),
290	            pending_cookie: self.pending.as_ref().map(|p| p.cookie),
291	        }
292	    }
293	    pub fn visible_scene(&self) -> Option<&S> {
294	        if !self.active || self.faulted || self.closed {
295	            return None;
296	        }
297	        self.front
298	            .as_ref()
299	            .and_then(|f| f.frame.payload.as_ref().map(|p| &p.scene))
300	    }
301	    pub fn submit<E>(
302	        &mut self,
303	        frame: PreparedFrame<R, S>,
304	        submit: impl FnOnce(Cookie, &R) -> SubmitOutcome<E>,
305	    ) -> Result<Cookie, SubmitError<R, S, E>> {
306	        self.submit_using(&LAST_COOKIE, frame, submit)
307	    }
308	    fn submit_using<E>(
309	        &mut self,
310	        counter: &AtomicU64,
311	        mut frame: PreparedFrame<R, S>,
312	        submit: impl FnOnce(Cookie, &R) -> SubmitOutcome<E>,
313	    ) -> Result<Cookie, SubmitError<R, S, E>> {
314	        let reason = if self.closed || !self.active || self.faulted {
315	            Some(Error::Inactive)
316	        } else if self.pending.is_some() {
317	            Some(Error::Pending)
318	        } else if !Rc::ptr_eq(
319	            &frame
320	                .payload
321	                .as_ref()
322	                .expect("prepared payload")
323	                .permit
324	                .pool
325	                .state,
326	            &self._output.pool.state,
327	        ) {
328	            Some(Error::WrongPool)
329	        } else {
330	            None
331	        };
332	        if let Some(reason) = reason {
333	            return Err(SubmitError::Admission { reason, frame });
334	        }
335	        let cookie = match allocate_cookie(counter) {
336	            Ok(cookie) => cookie,
337	            Err(reason) => {
338	                self.faulted = true;
339	                return Err(SubmitError::Admission { reason, frame });
340	            }
341	        };
342	        // Own it as uncertain BEFORE invoking platform code. An unwind cannot
343	        // drop a possibly submitted buffer or leave the old scene authoritative.
344	        frame.consuming = true;
345	        self.pending = Some(Pending { cookie, frame });
346	        self.faulted = true;
347	        let resource = &self
348	            .pending
349	            .as_ref()
350	            .expect("submitting frame owned")
351	            .frame
352	            .payload
353	            .as_ref()
354	            .expect("pending payload")
355	            .resource;
356	        match submit(cookie, resource) {
357	            SubmitOutcome::Accepted => {
358	                self.faulted = false;
359	                Ok(cookie)
360	            }
361	            SubmitOutcome::Rejected(error) => {
362	                let mut frame = self.pending.take().expect("submitting frame owned").frame;
363	                frame.consuming = false;
364	                self.faulted = false;
365	                Err(SubmitError::Rejected { error, frame })
366	            }
367	            SubmitOutcome::Uncertain(error) => Err(SubmitError::Uncertain(error)),
368	        }
369	    }
370	    pub fn complete(&mut self, source: Ticket, event: crate::drm_events::Flip) -> Completion {
371	        if !self.key.source_matches(source, event.crtc)
372	            || event.cookie == 0
373	            || self
374	                .pending
375	                .as_ref()
376	                .is_none_or(|p| p.cookie.get() != event.cookie)
377	        {
378	            return Completion::Ignored;
379	        }
380	        let pending = self.pending.take().expect("matching pending owned");
381	        if let Some(mut old) = self.front.take() {
382	            old.frame.consuming = false;
383	            drop(old);
384	        }
385	        self.front = Some(Front {
386	            cookie: pending.cookie,
387	            frame: pending.frame,
388	        });
389	        self.faulted = false;
390	        if self.active && !self.closed {
391	            Completion::Presented
392	        } else {
393	            Completion::RetiredProgress
394	        }
395	    }
396	    /// Stops publication/admission immediately, without pretending consumers idle.
397	    pub fn invalidate(&mut self) {
398	        self.active = false;
399	    }
400	    /// Missing completion is an uncertainty condition, never permission to free.
401	    pub fn timeout(&mut self) -> bool {
402	        if self.pending.is_some() {
403	            self.faulted = true;
404	            true
405	        } else {
406	            false
407	        }
408	    }
409	    pub fn release_after_disable(&mut self, proof: IdleProof) -> Result<(), Error> {
410	        if proof.key != self.key {
411	            return Err(Error::WrongProof);
412	        }
413	        self.active = false;
414	        self.closed = true;
415	        self.faulted = false;
416	        if let Some(front) = &mut self.front {
417	            front.frame.consuming = false;
418	        }
419	        if let Some(pending) = &mut self.pending {
420	            pending.frame.consuming = false;
421	        }
422	        self.front.take();
423	        self.pending.take();
424	        Ok(())
425	    }
426	}
